CREATE    VIEW [FO].[vwPostedPurchaseLedgerInvoices]
AS

SELECT DISTINCT 
	LT.SUBLEDGERVOUCHER AS Voucher, 
	VTR.INVOICE AS InvoiceNo, 
	VTR.DOCUMENTDATE AS [Document Date],
	LT.ACCOUNTINGDATE AS [Transaction Date],
	LT.MAINACCOUNT AS [Ledger Account],
	LT.[RICSCOSTCENTER] AS [Cost Centre],
	LT.DOCUMENTNUMBER AS [PO Number], 
	LT.[RICSPRODUCTCODE] AS Product, 
	LT.TRANSACTIONCURRENCYCODE AS Currency,
	LT.TRANSACTIONCURRENCYAMOUNT AS [Amount (Currency)],
	LT.ACCOUNTINGCURRENCYAMOUNT AS [Amount (GBP)],
	LT.[TEXT] AS [Transaction Text],
	--LT.AMOUNTMSTSECOND AS [Amount Secondary Currency], 
	VTB.ACCOUNTNUM AS [Vendor AccountNo],
	VTB.[NAME] AS [Vendor Name], 
	VTB.VENDGROUP AS [Vendor Group]

FROM [synapse_fo].[LEDGERTRANS_RICS] LT
	LEFT JOIN [synapse_fo].[VENDTRANS] VTR
	    ON LT.SUBLEDGERVOUCHER = VTR.VOUCHER
	LEFT JOIN [FO].[vwVendTable] VTB
	    ON VTR.ACCOUNTNUM = VTB.ACCOUNTNUM
WHERE 
	(
		LT.SUBLEDGERVOUCHER LIKE '%PI'
		OR VTR.VOUCHER LIKE 'REV%'
	)
